"""semaev_lib.py -- self-contained arithmetic for the blind re-derivation
TASK-20261017-ccd10c.  Written from scratch in this session; shares no code
with any repository module.  Everything is pure Python + numpy, with sympy
used only where stated (symbolic S_3/S_4 construction, symmetrisation, and
as an *independent* cross-check of the home-grown factoring code).

Contents
  F_p helpers           legendre, sqrt_mod_p, find_nonresidue
  Fp2                   F_{p^2} = F_p[w]/(w^2 - nr), with generic Tonelli-Shanks
  Curve                 y^2 = x^3 + a x + b over F_{p^2} (affine group law)
  univariate polys      dense lists low->high: pmul, pdivmod, pgcd, ppowmod,
                        is_squarefree, ddf_pattern (distinct-degree factoring)
  MPoly                 sparse multivariate polynomial over F_p with numpy
                        evaluation (F_p and F_{p^2} inputs)
  interpolation         inverse-Vandermonde grid interpolation, det_mod,
                        sylvester_det_mod
"""
import numpy as np
import random

# ----------------------------------------------------------------- F_p ----
def legendre(c, p):
    c %= p
    if c == 0:
        return 0
    return 1 if pow(c, (p - 1) // 2, p) == 1 else -1


def find_nonresidue(p):
    for z in range(2, p):
        if legendre(z, p) == -1:
            return z
    raise ValueError("no non-residue (p=2?)")


def sqrt_mod_p(c, p):
    """Tonelli-Shanks.  Returns r with r*r = c (mod p), or None."""
    c %= p
    if c == 0:
        return 0
    if legendre(c, p) != 1:
        return None
    if p % 4 == 3:
        return pow(c, (p + 1) // 4, p)
    q, s = p - 1, 0
    while q % 2 == 0:
        q //= 2
        s += 1
    z = find_nonresidue(p)
    m, cc, t, r = s, pow(z, q, p), pow(c, q, p), pow(c, (q + 1) // 2, p)
    while t != 1:
        i, t2 = 0, t
        while t2 != 1:
            t2 = t2 * t2 % p
            i += 1
        bb = pow(cc, 1 << (m - i - 1), p)
        m, cc, t, r = i, bb * bb % p, t * bb * bb % p, r * bb % p
    return r


# --------------------------------------------------------------- F_{p^2} ----
class Fp2:
    """Elements are pairs (u, v) meaning u + v*w, w^2 = nr (nr a non-residue)."""

    def __init__(self, p):
        self.p = p
        self.nr = find_nonresidue(p)
        self.zero = (0, 0)
        self.one = (1, 0)

    def emb(self, c):
        return (c % self.p, 0)

    def add(self, x, y):
        p = self.p
        return ((x[0] + y[0]) % p, (x[1] + y[1]) % p)

    def sub(self, x, y):
        p = self.p
        return ((x[0] - y[0]) % p, (x[1] - y[1]) % p)

    def neg(self, x):
        p = self.p
        return ((-x[0]) % p, (-x[1]) % p)

    def mul(self, x, y):
        p = self.p
        return ((x[0] * y[0] + self.nr * x[1] * y[1]) % p,
                (x[0] * y[1] + x[1] * y[0]) % p)

    def smul(self, c, x):
        p = self.p
        return (c * x[0] % p, c * x[1] % p)

    def inv(self, x):
        p = self.p
        n = (x[0] * x[0] - self.nr * x[1] * x[1]) % p
        if n == 0:
            raise ZeroDivisionError
        ni = pow(n, p - 2, p)
        return (x[0] * ni % p, (-x[1] * ni) % p)

    def norm(self, x):
        p = self.p
        return (x[0] * x[0] - self.nr * x[1] * x[1]) % p

    def frob(self, x):
        return (x[0], (-x[1]) % self.p)

    def pow(self, x, e):
        r = self.one
        while e:
            if e & 1:
                r = self.mul(r, x)
            e >>= 1
            if e:
                x = self.mul(x, x)
        return r

    def is_in_base(self, x):
        return x[1] == 0

    def sqrt_of_base(self, c):
        """Square root in F_{p^2} of c in F_p (always exists)."""
        p = self.p
        c %= p
        if c == 0:
            return (0, 0)
        if legendre(c, p) == 1:
            return (sqrt_mod_p(c, p), 0)
        # c = nr * (c/nr), c/nr is a residue; (v w)^2 = v^2 nr
        v = sqrt_mod_p(c * pow(self.nr, p - 2, p) % p, p)
        return (0, v)

    def is_square(self, x):
        if x == (0, 0):
            return True
        return self.pow(x, (self.p * self.p - 1) // 2) == self.one

    def sqrt(self, c, rng=None):
        """Generic Tonelli-Shanks in F_{p^2}; returns a root or None."""
        if c == (0, 0):
            return (0, 0)
        if c[1] == 0:
            return self.sqrt_of_base(c[0])
        if not self.is_square(c):
            return None
        q = self.p * self.p - 1
        s = 0
        while q % 2 == 0:
            q //= 2
            s += 1
        rng = rng or random.Random(1)
        while True:
            z = (rng.randrange(self.p), rng.randrange(self.p))
            if z != (0, 0) and not self.is_square(z):
                break
        m, cc, t, r = s, self.pow(z, q), self.pow(c, q), self.pow(c, (q + 1) // 2)
        while t != self.one:
            i, t2 = 0, t
            while t2 != self.one:
                t2 = self.mul(t2, t2)
                i += 1
            bb = self.pow(cc, 1 << (m - i - 1))
            m = i
            cc = self.mul(bb, bb)
            t = self.mul(t, cc)
            r = self.mul(r, bb)
        return r


# ---------------------------------------------------------------- curve ----
class Curve:
    """E: y^2 = x^3 + a x + b over F_p, p > 3, with group law over F_{p^2}.
    Points: None = O, else (x, y) with x, y in Fp2 pairs."""

    def __init__(self, p, a, b, name=None):
        self.p, self.a, self.b = p, a % p, b % p
        self.name = name or f"p{p}_a{a}_b{b}"
        if p <= 3:
            raise ValueError("p > 3 required")
        if (4 * self.a ** 3 + 27 * self.b ** 2) % p == 0:
            raise ValueError("singular curve")
        self.F = Fp2(p)

    # f(x) = x^3 + a x + b
    def f(self, x):
        p = self.p
        return (x * x * x + self.a * x + self.b) % p

    def f2(self, x):
        F = self.F
        return F.add(F.add(F.mul(F.mul(x, x), x), F.smul(self.a, x)), F.emb(self.b))

    def lift(self, x, sign=1):
        """Point with x in F_p: (x, sqrt(f(x))) in E(F_{p^2})."""
        y = self.F.sqrt_of_base(self.f(x))
        if sign < 0:
            y = self.F.neg(y)
        return (self.F.emb(x), y)

    def neg(self, P):
        return None if P is None else (P[0], self.F.neg(P[1]))

    def add(self, P, Q):
        if P is None:
            return Q
        if Q is None:
            return P
        F = self.F
        if P[0] == Q[0]:
            if F.add(P[1], Q[1]) == (0, 0):
                return None
            num = F.add(F.smul(3, F.mul(P[0], P[0])), F.emb(self.a))
            den = F.smul(2, P[1])
        else:
            num = F.sub(Q[1], P[1])
            den = F.sub(Q[0], P[0])
        lam = F.mul(num, F.inv(den))
        x3 = F.sub(F.sub(F.mul(lam, lam), P[0]), Q[0])
        y3 = F.sub(F.mul(lam, F.sub(P[0], x3)), P[1])
        return (x3, y3)

    def on_curve(self, P):
        if P is None:
            return True
        return self.F.mul(P[1], P[1]) == self.f2(P[0])

    def random_point_Fp(self, rng):
        while True:
            x = rng.randrange(self.p)
            fx = self.f(x)
            if legendre(fx, self.p) == 1:
                y = sqrt_mod_p(fx, self.p)
                if rng.random() < 0.5:
                    y = (-y) % self.p
                return (self.F.emb(x), self.F.emb(y))

    def random_point_Fp2(self, rng):
        while True:
            x = (rng.randrange(self.p), rng.randrange(self.p))
            fx = self.f2(x)
            if fx == (0, 0):
                continue
            y = self.F.sqrt(fx, rng)
            if y is not None:
                if rng.random() < 0.5:
                    y = self.F.neg(y)
                return (x, y)

    def point_counts(self):
        """Exact counts over F_p by brute force: returns dict with
        n_points, t, N0 (roots of f), Nplus, Nminus."""
        p = self.p
        N0 = Np = Nm = 0
        for x in range(p):
            s = legendre(self.f(x), p)
            if s == 0:
                N0 += 1
            elif s == 1:
                Np += 1
            else:
                Nm += 1
        n = 1 + N0 + 2 * Np
        return dict(n_points=n, t=p + 1 - n, N0=N0, Nplus=Np, Nminus=Nm)


# --------------------------------------------------- univariate polys ----
def ptrim(a):
    while a and a[-1] == 0:
        a.pop()
    return a


def pnorm(a, p):
    return ptrim([c % p for c in a])


def padd(a, b, p):
    n = max(len(a), len(b))
    r = [0] * n
    for i, c in enumerate(a):
        r[i] = c
    for i, c in enumerate(b):
        r[i] = (r[i] + c) % p
    return ptrim(r)


def psub(a, b, p):
    n = max(len(a), len(b))
    r = [0] * n
    for i, c in enumerate(a):
        r[i] = c
    for i, c in enumerate(b):
        r[i] = (r[i] - c) % p
    return ptrim(r)


def pmul(a, b, p):
    if not a or not b:
        return []
    r = [0] * (len(a) + len(b) - 1)
    for i, c in enumerate(a):
        if c:
            for j, d in enumerate(b):
                r[i + j] += c * d
    return ptrim([c % p for c in r])


def pdivmod(a, b, p):
    a = pnorm(a, p)
    b = pnorm(b, p)
    if not b:
        raise ZeroDivisionError
    db = len(b) - 1
    if len(a) < len(b):
        return [], a
    inv = pow(b[-1], p - 2, p)
    q = [0] * (len(a) - db)
    for i in range(len(a) - 1, db - 1, -1):
        c = a[i]
        if c:
            fct = c * inv % p
            q[i - db] = fct
            for j in range(db + 1):
                a[i - db + j] = (a[i - db + j] - fct * b[j]) % p
    return ptrim(q), ptrim(a[:db])


def pmonic(a, p):
    a = pnorm(a, p)
    if not a:
        return a
    inv = pow(a[-1], p - 2, p)
    return [c * inv % p for c in a]


def pgcd(a, b, p):
    a = pnorm(a, p)
    b = pnorm(b, p)
    while b:
        _, r = pdivmod(a, b, p)
        a, b = b, r
    return pmonic(a, p)


def ppowmod(base, e, mod, p):
    result = [1]
    base = pdivmod(base, mod, p)[1]
    while e:
        if e & 1:
            result = pdivmod(pmul(result, base, p), mod, p)[1]
        e >>= 1
        if e:
            base = pdivmod(pmul(base, base, p), mod, p)[1]
    return result


def pderiv(a, p):
    return ptrim([(i * c) % p for i, c in enumerate(a)][1:])


def peval(a, x, p):
    r = 0
    for c in reversed(a):
        r = (r * x + c) % p
    return r


def is_squarefree(a, p):
    a = pnorm(a, p)
    if len(a) <= 1:
        return len(a) == 1
    g = pgcd(a, pderiv(a, p), p)
    return len(g) == 1


def ddf_pattern(Fpoly, p):
    """Distinct-degree factorisation of a squarefree polynomial over F_p.
    Returns the sorted list of degrees of its irreducible factors, i.e. the
    cycle type of the p-power Frobenius on its roots."""
    Fm = pmonic(Fpoly, p)
    pattern = []
    h = [0, 1]  # X
    k = 0
    while len(Fm) - 1 >= 2 * (k + 1):
        k += 1
        h = ppowmod(h, p, Fm, p)          # X^{p^k} mod F
        g = pgcd(Fm, psub(h, [0, 1], p), p)
        if len(g) > 1:
            dg = len(g) - 1
            if dg % k:
                raise RuntimeError("DDF: degree not divisible; input not squarefree?")
            pattern += [k] * (dg // k)
            Fm, r = pdivmod(Fm, g, p)
            if r:
                raise RuntimeError("DDF: non-exact division")
            h = pdivmod(h, Fm, p)[1]
    if len(Fm) > 1:
        pattern.append(len(Fm) - 1)
    return sorted(pattern)


def cycle_type_str(pattern):
    """'1^4', '2^2', '2^1 1^2' style (descending degrees)."""
    from collections import Counter
    c = Counter(pattern)
    return " ".join(f"{d}^{c[d]}" for d in sorted(c, reverse=True))


def roots_in_Fp(a, p):
    """All roots in F_p of a univariate polynomial (brute force)."""
    return [x for x in range(p) if peval(a, x, p) == 0]


# ------------------------------------------------- multivariate polys ----
class MPoly:
    """Sparse polynomial over F_p in k variables: exps (N,k) int64, coefs (N,)."""

    def __init__(self, exps, coefs, p):
        exps = np.asarray(exps, dtype=np.int64).reshape(-1, len(exps[0]) if len(exps) else 0)
        coefs = np.asarray(coefs, dtype=np.int64) % p
        keep = coefs != 0
        self.exps = exps[keep]
        self.coefs = coefs[keep]
        self.p = p
        self.k = self.exps.shape[1]
        self.d = int(self.exps.max()) if len(self.exps) else 0
        self.degs = [int(self.exps[:, i].max()) if len(self.exps) else 0 for i in range(self.k)]

    @classmethod
    def from_dict(cls, dct, p):
        items = sorted(dct.items())
        return cls([e for e, _ in items], [c for _, c in items], p)

    def to_dict(self):
        return {tuple(int(v) for v in e): int(c) for e, c in zip(self.exps, self.coefs)}

    def nterms(self):
        return int(len(self.coefs))

    def canonical_bytes(self):
        return ("\n".join(f"{' '.join(map(str, e))}:{c}" for e, c in sorted(self.to_dict().items()))).encode()

    # -- evaluation over F_p --
    def _powtab(self, xs):
        p = self.p
        tab = np.ones((self.k, self.d + 1), dtype=np.int64)
        for i, x in enumerate(xs):
            x %= p
            for e in range(1, self.d + 1):
                tab[i, e] = tab[i, e - 1] * x % p
        return tab

    def eval(self, xs):
        """Value at xs (all k variables given, ints mod p)."""
        p = self.p
        tab = self._powtab(xs)
        vals = self.coefs.copy()
        for i in range(self.k):
            vals = vals * tab[i][self.exps[:, i]] % p
        return int(vals.sum() % p)

    def tpoly(self, xs):
        """Coefficient list (low->high) in the LAST variable after substituting
        the first k-1 variables by xs."""
        p = self.p
        assert len(xs) == self.k - 1
        tab = self._powtab(list(xs) + [0])
        vals = self.coefs.copy()
        for i in range(self.k - 1):
            vals = vals * tab[i][self.exps[:, i]] % p
        acc = np.bincount(self.exps[:, self.k - 1], weights=vals.astype(np.float64),
                          minlength=self.degs[self.k - 1] + 1)
        # exact: each weight < p, at most N terms, sum < 2^53
        return ptrim([int(round(v)) % p for v in acc])

    # -- evaluation over F_{p^2} (inputs are pairs) --
    def eval2(self, xs, F):
        p = self.p
        nr = F.nr
        U = np.ones((self.k, self.d + 1), dtype=np.int64)
        V = np.zeros((self.k, self.d + 1), dtype=np.int64)
        for i, (u, v) in enumerate(xs):
            for e in range(1, self.d + 1):
                U[i, e] = (U[i, e - 1] * u + nr * V[i, e - 1] * v) % p
                V[i, e] = (U[i, e - 1] * v + V[i, e - 1] * u) % p
        au = self.coefs.copy()
        av = np.zeros_like(au)
        for i in range(self.k):
            bu = U[i][self.exps[:, i]]
            bv = V[i][self.exps[:, i]]
            au, av = (au * bu + nr * av * bv) % p, (au * bv + av * bu) % p
        return (int(au.sum() % p), int(av.sum() % p))

    def permuted(self, perm):
        """Polynomial with variables permuted: new exps[:, j] = exps[:, perm[j]]."""
        return MPoly(self.exps[:, list(perm)], self.coefs, self.p)

    def equals(self, other):
        return self.to_dict() == other.to_dict()


# ---------------------------------------------------- interpolation ----
def det_mod(M, p):
    """Determinant mod p by Gaussian elimination (M list of lists)."""
    n = len(M)
    A = [[c % p for c in row] for row in M]
    det = 1
    for col in range(n):
        piv = None
        for r in range(col, n):
            if A[r][col]:
                piv = r
                break
        if piv is None:
            return 0
        if piv != col:
            A[col], A[piv] = A[piv], A[col]
            det = -det
        pv = A[col][col]
        det = det * pv % p
        inv = pow(pv, p - 2, p)
        for r in range(col + 1, n):
            if A[r][col]:
                fct = A[r][col] * inv % p
                rowc = A[col]
                rowr = A[r]
                for c in range(col, n):
                    rowr[c] = (rowr[c] - fct * rowc[c]) % p
    return det % p


def sylvester_det_mod(A, B, p):
    """Resultant Res_X(A, B) with FORMAL degrees len(A)-1 and len(B)-1 (the
    Sylvester matrix is always built at full formal size, so that this equals
    the specialisation of the formal resultant).  Coefficient lists low->high."""
    m, n = len(A) - 1, len(B) - 1
    N = m + n
    M = [[0] * N for _ in range(N)]
    Ah = [c % p for c in A[::-1]]
    Bh = [c % p for c in B[::-1]]
    for i in range(n):
        for j, c in enumerate(Ah):
            M[i][i + j] = c
    for i in range(m):
        for j, c in enumerate(Bh):
            M[n + i][i + j] = c
    return det_mod(M, p)


def inv_vandermonde(d, p):
    n = d + 1
    V = [[pow(i, j, p) for j in range(n)] for i in range(n)]
    A = [row[:] + [1 if r == c else 0 for c in range(n)] for r, row in enumerate(V)]
    for col in range(n):
        piv = next(r for r in range(col, n) if A[r][col])
        A[col], A[piv] = A[piv], A[col]
        inv = pow(A[col][col], p - 2, p)
        A[col] = [c * inv % p for c in A[col]]
        for r in range(n):
            if r != col and A[r][col]:
                fct = A[r][col]
                A[r] = [(x - fct * y) % p for x, y in zip(A[r], A[col])]
    return np.array([row[n:] for row in A], dtype=np.int64)


def interpolate_grid(vals, d, p):
    """vals: numpy array of shape (d+1,)*k holding P(i_1,...,i_k) for nodes
    0..d.  Returns C with C[e_1,...,e_k] = coefficient of x_1^e_1...x_k^e_k,
    exact for a polynomial of degree <= d in each variable."""
    Vinv = inv_vandermonde(d, p)
    C = np.asarray(vals, dtype=np.int64) % p
    k = C.ndim
    for axis in range(k):
        C = np.tensordot(Vinv, C, axes=([1], [axis])) % p
        C = np.moveaxis(C, 0, axis)
    return C


def mpoly_from_array(C, p):
    nz = np.argwhere(C % p != 0)
    coefs = [int(C[tuple(e)]) for e in nz]
    return MPoly(nz, coefs, p)

